"""Claude access for every stage, traced by neatlogs.

- One Anthropic client, wrapped by neatlogs so every model call is recorded.
- Structured outputs via ``messages.parse`` so each stage gets a validated object.
- One repair attempt when the output does not validate, then the stage fails.
- On overload or rate limits after the SDK's own retries, switch to a fallback model.
- Cost and tokens are added to the current job so the UI and evals can report them.
"""

from __future__ import annotations

import base64
import contextlib
import contextvars
import os
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterator, TypeVar

import anthropic
from pydantic import BaseModel, ValidationError

from .config import price_for, settings

T = TypeVar("T", bound=BaseModel)

_tracing = False
try:
    import neatlogs

    if os.getenv("NEATLOGS_API_KEY"):
        neatlogs.init(
            api_key=os.environ["NEATLOGS_API_KEY"],
            endpoint=settings.neatlogs_endpoint,
            workflow_name="niyam-rule-sync",
            tags=["niyam", "neathack"],
        )
        _tracing = True
except Exception as exc:  # tracing must never stop the agent
    print(f"[niyam] neatlogs tracing disabled: {exc}")

_client = anthropic.Anthropic(max_retries=3, timeout=600)
client = neatlogs.wrap(_client) if _tracing else _client


@dataclass
class Usage:
    cost_usd: float = 0.0
    tokens_in: int = 0
    tokens_out: int = 0
    calls: int = 0

    def add(self, model: str, usage: Any) -> None:
        p_in, p_out = price_for(model)
        tin = (usage.input_tokens or 0) + (getattr(usage, "cache_creation_input_tokens", 0) or 0) * 1.25
        cached = getattr(usage, "cache_read_input_tokens", 0) or 0
        self.tokens_in += int((usage.input_tokens or 0) + cached)
        self.tokens_out += int(usage.output_tokens or 0)
        self.cost_usd += (tin * p_in + cached * p_in * 0.1 + (usage.output_tokens or 0) * p_out) / 1_000_000
        self.calls += 1


current_usage: contextvars.ContextVar[Usage | None] = contextvars.ContextVar("usage", default=None)
chaos_used: contextvars.ContextVar[set[str] | None] = contextvars.ContextVar("chaos_used", default=None)


class StageOutputError(RuntimeError):
    pass


@contextlib.contextmanager
def span(name: str, kind: str = "AGENT") -> Iterator[Any]:
    """A neatlogs span, or a no-op when tracing is off."""
    if not _tracing:
        yield None
        return
    with neatlogs.trace(name, kind=kind) as s:
        yield s


def set_attr(s: Any, key: str, value: Any) -> None:
    if s is not None and hasattr(s, "set_attribute"):
        try:
            s.set_attribute(key, value if isinstance(value, (str, int, float, bool)) else str(value))
        except Exception:
            pass


def current_trace_id() -> str | None:
    if _tracing:
        try:
            carrier: dict[str, str] = {}
            if neatlogs.inject_trace_context(carrier) and carrier.get("traceparent"):
                return carrier["traceparent"].split("-")[1]
        except Exception:
            pass
    try:
        from opentelemetry import trace as ot

        ctx = ot.get_current_span().get_span_context()
        return format(ctx.trace_id, "032x") if ctx and ctx.trace_id else None
    except Exception:
        return None


def pdf_block(path: Path) -> dict[str, Any]:
    data = base64.standard_b64encode(Path(path).read_bytes()).decode("ascii")
    return {"type": "document", "source": {"type": "base64", "media_type": "application/pdf", "data": data}}


def image_block(png: bytes) -> dict[str, Any]:
    return {"type": "image", "source": {"type": "base64", "media_type": "image/png",
                                         "data": base64.standard_b64encode(png).decode("ascii")}}


def parse(*, model: str, system: str, content: list[dict[str, Any]] | str, output: type[T],
          max_tokens: int = 16000, effort: str | None = None, stage: str = "llm") -> T:
    """Call Claude and return a validated ``output`` instance."""
    messages: list[dict[str, Any]] = [{"role": "user", "content": content}]
    models = [model] + ([settings.model_fallback] if settings.model_fallback != model else [])
    last_error: Exception | None = None
    for m in models:
        for attempt in range(2):  # first try, then one repair attempt
            kwargs: dict[str, Any] = dict(model=m, max_tokens=max_tokens, system=system,
                                          messages=messages, output_format=output)
            if effort and not m.startswith("claude-haiku-4"):
                kwargs["output_config"] = {"effort": effort}
            try:
                resp = client.messages.parse(**kwargs)
            except (anthropic.RateLimitError, anthropic.InternalServerError, anthropic.APIConnectionError) as e:
                last_error = e
                _record_event("recovery.model_fallback", f"{m} unavailable ({type(e).__name__}); trying the fallback model")
                break
            except anthropic.APIStatusError as e:
                if e.status_code == 529:
                    last_error = e
                    _record_event("recovery.model_fallback", f"{m} overloaded; trying the fallback model")
                    break
                raise
            usage = current_usage.get()
            if usage is not None:
                usage.add(m, resp.usage)
            if resp.stop_reason == "refusal":
                raise StageOutputError(f"{stage}: the model declined the request")
            parsed = resp.parsed_output
            injected = _chaos_once("invalid_json") and attempt == 0
            if parsed is not None and not injected:
                return parsed
            text = "".join(b.text for b in resp.content if getattr(b, "type", "") == "text")
            reason = "injected test failure (chaos flag)" if injected else f"output did not match the schema (stop_reason={resp.stop_reason})"
            _record_event("recovery.json_repair", f"{stage}: {reason}; asking the model to repair it")
            messages = messages + [
                {"role": "assistant", "content": text or "(empty)"},
                {"role": "user", "content": f"Your previous answer could not be used: {reason}. Reply again with only the requested structure, complete and valid."},
            ]
            last_error = StageOutputError(reason)
    raise StageOutputError(f"{stage}: no valid output after repair and fallback ({last_error})")


# The orchestrator sets this so llm.py can write recovery events to the job timeline.
_event_sink: contextvars.ContextVar[Any] = contextvars.ContextVar("event_sink", default=None)


def _record_event(kind: str, message: str) -> None:
    sink = _event_sink.get()
    if sink:
        sink(kind, message)
    with span(kind, kind="CHAIN") as s:
        set_attr(s, "niyam.recovery", message)


def _chaos_once(name: str) -> bool:
    if name not in settings.chaos:
        return False
    used = chaos_used.get()
    if used is None or name in used:
        return False
    used.add(name)
    return True


def flush() -> None:
    if _tracing:
        try:
            neatlogs.flush()
        except Exception:
            pass


def shutdown() -> None:
    if _tracing:
        try:
            neatlogs.flush()
            neatlogs.shutdown()
        except Exception:
            pass


def tracing_enabled() -> bool:
    return _tracing


def now() -> float:
    return time.time()

"""PDF text, and the check that every quoted clause really is in the document.

Text layers of Marathi government PDFs are often damaged by font encoding:
the vowel sign ि comes out as ह, a reph (र्) comes out as ण, and so on. Exact
string matching would reject real quotes, so quotes are compared on a
"consonant skeleton": vowel signs, viramas, spaces, punctuation and the letters
most often corrupted are removed from both sides, then compared fuzzily.
"""

from __future__ import annotations

import difflib
import hashlib
import re
import unicodedata
from dataclasses import dataclass
from pathlib import Path

import pypdf

_DEV_DIGITS = str.maketrans("०१२३४५६७८९", "0123456789")
# Letters that broken font encodings most often produce or swallow.
_UNSTABLE = set("हणरल")


def skeleton(text: str) -> str:
    text = unicodedata.normalize("NFC", text).translate(_DEV_DIGITS)
    out = []
    for ch in text:
        cp = ord(ch)
        if 0x0915 <= cp <= 0x0939 or 0x0958 <= cp <= 0x095F or 0x0904 <= cp <= 0x0914:
            if ch not in _UNSTABLE:
                out.append(ch)
        elif ch.isascii() and ch.isalnum():
            out.append(ch.lower())
    return "".join(out)


@dataclass
class PdfText:
    path: Path
    pages: list[str]
    sha256: str

    @property
    def page_count(self) -> int:
        return len(self.pages)

    def low_text_pages(self, min_chars: int = 80) -> list[int]:
        return [i + 1 for i, t in enumerate(self.pages) if len(t.strip()) < min_chars]

    def joined(self, max_pages: int | None = None) -> str:
        pages = self.pages[:max_pages] if max_pages else self.pages
        return "\n".join(f"=== PAGE {i} ===\n{t}" for i, t in enumerate(pages, 1))


def read_pdf(path: Path | str) -> PdfText:
    path = Path(path)
    data = path.read_bytes()
    if not data.startswith(b"%PDF"):
        raise ValueError("not a PDF file")
    reader = pypdf.PdfReader(path)
    pages = []
    for p in reader.pages:
        try:
            pages.append(p.extract_text() or "")
        except Exception:
            pages.append("")
    return PdfText(path=path, pages=pages, sha256=hashlib.sha256(data).hexdigest())


@dataclass
class QuoteMatch:
    found: bool
    page: int | None
    score: float
    cited_page_score: float


def find_quote(doc_pages: list[str], quote: str, cited_page: int | None, threshold: float = 0.78) -> QuoteMatch:
    """Find a quote on the cited page (or anywhere, if the page number is off by one)."""
    q = skeleton(quote)
    if len(q) < 4:
        return QuoteMatch(False, None, 0.0, 0.0)

    def best(page_text: str) -> float:
        s = skeleton(page_text)
        if not s:
            return 0.0
        if q in s:
            return 1.0
        n = len(q)
        top = 0.0
        step = max(1, n // 8)
        for i in range(0, max(1, len(s) - n + 1), step):
            window = s[i:i + n + n // 5]
            r = difflib.SequenceMatcher(None, q, window, autojunk=False).ratio()
            if r > top:
                top = r
                if top > 0.97:
                    break
        return top

    # Numbers decide eligibility, so they must match exactly: every digit run in
    # the quote has to appear on the page (fuzzy matching would accept 75 for 65).
    digit_runs = re.findall(r"\d+", q)

    def numbers_ok(page_text: str) -> bool:
        s = skeleton(page_text)
        return all(run in s for run in digit_runs)

    scores = {i + 1: (best(t) if numbers_ok(t) else 0.0) for i, t in enumerate(doc_pages)}
    cited = scores.get(cited_page or -1, 0.0)
    if cited >= threshold:
        return QuoteMatch(True, cited_page, cited, cited)
    # Allow a neighbouring page: table rows often continue across a page break.
    page, score = max(scores.items(), key=lambda kv: kv[1]) if scores else (None, 0.0)
    near = cited_page is None or (page is not None and abs(page - cited_page) <= 1)
    return QuoteMatch(score >= threshold and near, page, score, cited)


_GR_CODE = re.compile(r"(?<!\d)(20\d{16})(?!\d)")


def find_gr_code(text: str) -> str | None:
    codes = _GR_CODE.findall(text.translate(_DEV_DIGITS))
    return codes[-1] if codes else None

"""Confidence score and the autonomy policy: when Niyam may merge on its own."""

from __future__ import annotations

from typing import Any

from .models import ChangeSet

TYPE_SAFETY = {
    "parameter_update": 1.0, "effective_date_changed": 0.9, "benefit_changed": 0.8,
    "condition_changed": 0.6, "condition_added": 0.5, "condition_removed": 0.5,
    "definition_changed": 0.4, "scheme_created": 0.3, "scheme_closed": 0.3,
}
STRUCTURAL = {"condition_added", "condition_removed", "condition_changed", "definition_changed",
              "scheme_created", "scheme_closed"}


def score(cs: ChangeSet, verdict: dict[str, Any] | None, tests_ok: bool, rejected_quotes: int) -> float:
    if not cs.changes:
        return 0.0
    extraction = sum(c.confidence for c in cs.changes) / len(cs.changes)
    extraction *= max(0.0, 1 - 0.15 * rejected_quotes)
    agreement = (verdict or {}).get("agreement_rate", 0.0)
    safety = min(TYPE_SAFETY.get(c.change_type, 0.4) for c in cs.changes)
    return round(0.35 * extraction + 0.35 * agreement + 0.15 * (1.0 if tests_ok else 0.0) + 0.15 * safety, 3)


def decide(cs: ChangeSet, confidence: float, verdict: dict[str, Any] | None, unresolved: int,
           is_byod: bool) -> tuple[str, list[str]]:
    """Returns (decision, reasons). Decisions: auto_merge, human_review, needs_human."""
    reasons: list[str] = []
    if is_byod:
        reasons.append("Uploaded documents run on a sandbox branch and are never merged automatically.")
    if any(c.affects in ("narrows", "mixed") for c in cs.changes):
        reasons.append("At least one change removes people from a scheme. Niyam never does that without a human.")
    structural = sorted({c.change_type for c in cs.changes} & STRUCTURAL)
    if structural:
        reasons.append(f"Structural change ({', '.join(structural)}), not only a number or a date.")
    if cs.ambiguities:
        reasons.append(f"{len(cs.ambiguities)} ambiguous clause(s) flagged during extraction.")
    if unresolved:
        reasons.append(f"{unresolved} disagreement(s) between the encoder and the verifier are unresolved.")
    if verdict and verdict.get("cases_disagree"):
        reasons.append("The verifier still disagrees on some test citizens.")
    if confidence < 0.9:
        reasons.append(f"Confidence {confidence:.2f} is below the 0.90 needed to merge alone.")

    if unresolved or confidence < 0.7 or (cs.ambiguities and confidence < 0.8):
        return "needs_human", reasons
    if reasons:
        return "human_review", reasons
    return "auto_merge", ["Only numbers or dates changed, every boundary test agrees, and confidence is at least 0.90."]

"""The agent's view of the rulebook repository: worktrees, rules for prompts,
simulation on a branch, and tests. Everything runs as a subprocess against a
specific checkout, so a job can never read or write another job's files."""

from __future__ import annotations

import json
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Any

import yaml

from .config import settings

PY = sys.executable
ALLOWED_PREFIXES = ("schemes/", "parameters/", "tests/", "sources/", "glossary/", "schema/", "CHANGELOG.md")


def git(*args: str, cwd: Path, check: bool = True, timeout: int = 300) -> str:
    env = {**os.environ, "GIT_TERMINAL_PROMPT": "0"}
    proc = subprocess.run(["git", *args], cwd=cwd, capture_output=True, text=True, encoding="utf-8",
                          errors="replace", timeout=timeout, env=env, stdin=subprocess.DEVNULL)
    if check and proc.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)} failed: {proc.stderr.strip() or proc.stdout.strip()}")
    return proc.stdout.strip()


def rb_cli(cwd: Path, *args: str, timeout: int = 120) -> subprocess.CompletedProcess:
    env = {**os.environ, "PYTHONIOENCODING": "utf-8", "PYTHONPATH": str(cwd)}
    return subprocess.run([PY, "-m", "niyam_rulebook", *args], cwd=cwd, capture_output=True, text=True,
                          encoding="utf-8", errors="replace", timeout=timeout, env=env, stdin=subprocess.DEVNULL)


def main_path() -> Path:
    return settings.rulebook_path


def sync_main() -> None:
    """Bring the local main checkout up to date with the published rulebook."""
    root = main_path()
    if settings.publish_mode == "github":
        git("fetch", "-q", "origin", cwd=root, check=False)
        git("checkout", "-q", "main", cwd=root, check=False)
        git("merge", "-q", "--ff-only", "origin/main", cwd=root, check=False)


def create_worktree(job_id: str, base: str = "main") -> tuple[Path, str]:
    root = main_path()
    branch = f"niyam/{job_id}"
    path = settings.work_dir / job_id
    if path.exists():  # resume after a crash: reuse the existing worktree
        return path, branch
    path.parent.mkdir(parents=True, exist_ok=True)
    existing = git("branch", "--list", branch, cwd=root)
    if existing:
        git("worktree", "add", "-q", str(path), branch, cwd=root)
    else:
        git("worktree", "add", "-q", "-b", branch, str(path), base, cwd=root)
    git("config", "user.name", "Niyam Agent", cwd=path)
    git("config", "user.email", os.getenv("NIYAM_GIT_EMAIL", "ujwalvanjare6@gmail.com"), cwd=path)
    return path, branch


def base_checkout(ref: str) -> Path:
    """A clean, read-only checkout of the rulebook at a ref: the rules *before* a document.
    Extraction and verification read old rules from here, never from main (which moves
    when changes merge) and never from the job's worktree (which holds the change)."""
    root = main_path()
    sha = git("rev-parse", ref, cwd=root)
    path = settings.work_dir / f"base-{sha[:12]}"
    if not path.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
        git("worktree", "add", "-q", "--detach", str(path), sha, cwd=root)
    return path


def remove_worktree(job_id: str) -> None:
    path = settings.work_dir / job_id
    if path.exists():
        git("worktree", "remove", "--force", str(path), cwd=main_path(), check=False)
        shutil.rmtree(path, ignore_errors=True)


def scheme_ids(root: Path | None = None) -> list[str]:
    root = root or main_path()
    out = []
    for p in sorted((root / "schemes").rglob("*.yaml")):
        out.append(yaml.safe_load(p.read_text(encoding="utf-8"))["id"])
    return out


def schemes_overview(root: Path | None = None) -> str:
    root = root or main_path()
    lines = []
    for p in sorted((root / "schemes").rglob("*.yaml")):
        d = yaml.safe_load(p.read_text(encoding="utf-8"))
        lines.append(f"- {d['id']}: {d['name']} ({d.get('name_mr', '')}). {d.get('summary', '')}")
    return "\n".join(lines)


def rules_json(scheme_id: str, on: str | None, root: Path | None = None) -> dict[str, Any]:
    args = ["rules", scheme_id] + (["--date", on] if on else [])
    proc = rb_cli(root or main_path(), *args)
    if proc.returncode != 0:
        raise RuntimeError(proc.stderr)
    return json.loads(proc.stdout)


def rules_for_prompt(scheme_id: str, on: str | None, root: Path | None = None) -> str:
    if not scheme_data(scheme_id, root):
        return (f"Scheme {scheme_id} does not exist in the rulebook yet. This document creates it: report one scheme_created "
                "change, then every eligibility or disqualification condition as condition_added (with new_value set to a "
                "rule expression over person fields), every number or list as parameter_update with old_value null, and the "
                "monthly benefit as benefit_changed.")
    r = rules_json(scheme_id, on, root)
    lines = [f"Scheme {r['id']} ({r['name']}) as of {r['as_of']}", "Parameters:"]
    for name, p in r["parameters"].items():
        lines.append(f"  - {name} = {json.dumps(p['value'], ensure_ascii=False)} (since {p['since']}; {p['description']})")
    lines.append("Conditions (all must be true):")
    for c in r["conditions"]:
        lines.append(f"  - [{c['id']}] {c['text']}  | expression: {c['when']}  | source clause {c['source'].get('clause')}")
    # The benefit formula decides how much is paid. Without it, an agent cannot
    # predict amounts (found from traces: verifier and coordinator looped on it).
    benefit = scheme_data(scheme_id, root).get("benefit") or {}
    if benefit.get("monthly_inr"):
        src = benefit.get("source") or {}
        lines.append(f"Monthly benefit paid when eligible: {benefit['monthly_inr']}  | source clause {src.get('clause')}: "
                     f"\"{src.get('quote_en', '')}\"")
    return "\n".join(lines)


def scheme_data(scheme_id: str, root: Path | None = None) -> dict[str, Any]:
    for p in sorted(((root or main_path()) / "schemes").rglob("*.yaml")):
        d = yaml.safe_load(p.read_text(encoding="utf-8"))
        if d.get("id") == scheme_id:
            return d
    return {}


def person_schema_text(root: Path | None = None) -> str:
    root = root or main_path()
    data = yaml.safe_load((root / "schema" / "person.yaml").read_text(encoding="utf-8"))["fields"]
    lines = []
    for name, spec in data.items():
        kind = spec["type"] + (f" one of {spec['values']}" if spec.get("values") else "")
        lines.append(f"  - {name} ({kind}, default {spec.get('default')!r}): {spec.get('label', '')}")
    return "\n".join(lines)


def glossary_text(root: Path | None = None) -> str:
    p = (root or main_path()) / "glossary" / "maharashtra.md"
    return p.read_text(encoding="utf-8") if p.exists() else ""


def run_tests(root: Path) -> dict[str, Any]:
    proc = rb_cli(root, "test", "--json")
    try:
        data = json.loads(proc.stdout)
    except json.JSONDecodeError:
        data = {"passed": 0, "failed": 1, "failures": [{"case": "test run crashed", "problems": [proc.stderr[-2000:]]}],
                "check_problems": []}
    data["ok"] = proc.returncode == 0
    return data


def simulate_batch(root: Path, cases: list[dict[str, Any]]) -> list[dict[str, Any]]:
    with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False, encoding="utf-8") as f:
        json.dump(cases, f, ensure_ascii=False)
        tmp = f.name
    try:
        proc = rb_cli(root, "simulate-batch", tmp)
        if proc.returncode != 0:
            raise RuntimeError(proc.stderr[-2000:])
        return json.loads(proc.stdout)
    finally:
        os.unlink(tmp)


def changed_files(root: Path, base: str = "HEAD") -> list[str]:
    # Compare with the worktree's own starting commit. Comparing with main was a bug:
    # when main moved on, untouched files looked "changed" and the guard reverted them.
    out = git("diff", "--name-only", base, cwd=root)
    untracked = git("ls-files", "--others", "--exclude-standard", cwd=root)
    return sorted(set(filter(None, out.splitlines() + untracked.splitlines())))


def disallowed_changes(files: list[str]) -> list[str]:
    return [f for f in files if not f.startswith(ALLOWED_PREFIXES)]

"""Stage 7, publish: open a pull request with sources and proof, then merge only if allowed."""

from __future__ import annotations

import json
import os
import subprocess
from pathlib import Path
from typing import Any

from .. import rulebook
from ..config import settings
from ..models import ChangeSet

DECISION_TEXT = {
    "auto_merge": "Merged automatically: only numbers or dates changed and every check agreed.",
    "human_review": "Waiting for a human reviewer.",
    "needs_human": "Needs a human decision before this can be merged.",
}


def _gh(*args: str, cwd: Path) -> subprocess.CompletedProcess:
    return subprocess.run(["gh", *args], cwd=cwd, capture_output=True, text=True, encoding="utf-8",
                          errors="replace", timeout=180, stdin=subprocess.DEVNULL, env={**os.environ, "GH_PROMPT_DISABLED": "1"})


def pr_body(job: dict[str, Any], cs: ChangeSet, verdict: dict[str, Any] | None, resolutions: list[dict[str, Any]],
            confidence: float, decision: str, reasons: list[str], checkpoint: str | None, commit_sha: str,
            trace_id: str | None, encode_summary: str) -> str:
    lines = ["## What changed"]
    for c in cs.changes:
        lines.append(f"- **{c.scheme_id}**: {c.summary} (from {c.effective_from}; {c.affects} eligibility)")
    if cs.skipped:
        lines.append("\nNot modelled (procedure or paperwork only): " + "; ".join(s.topic for s in cs.skipped))
    lines.append(f"\n## Source\n{cs.title_en}  \nGR {cs.document_code or ''} dated {cs.document_date or ''}")
    for c in cs.changes:
        q = c.citation
        lines.append(f"\n> {q.quote_original}\n>\n> *{q.quote_english}* (page {q.page}, clause {q.clause})")
    lines.append("\n## Verification")
    if verdict:
        lines.append(f"An independent verifier wrote {verdict['cases_valid']} test citizens from the document alone, "
                     f"without seeing this change. {verdict['cases_agree']} agree with the new rules"
                     + (f", {verdict['cases_disagree']} disagree." if verdict['cases_disagree'] else "."))
    for r in resolutions:
        lines.append(f"- Resolved `{r.get('case_name')}`: **{r.get('decision')}**. {r.get('explanation')}")
    if cs.ambiguities:
        lines.append("\n## Questions for a human")
        for a in cs.ambiguities:
            lines.append(f"- {a.question} Readings: " + " / ".join(a.readings))
    lines.append(f"\n## Decision\nConfidence **{confidence:.2f}**. {DECISION_TEXT[decision]}")
    for r in reasons:
        lines.append(f"- {r}")
    lines.append("\n## Evidence")
    if checkpoint:
        lines.append(f"- Entire checkpoint `{checkpoint}`: https://entire.io/gh/{settings.rulebook_repo}/commit/{commit_sha}")
    if trace_id:
        lines.append(f"- neatlogs trace id `{trace_id}`")
    lines.append(f"- Niyam job `{job['id']}`")
    if encode_summary:
        lines.append(f"\n<details><summary>Encoder summary</summary>\n\n{encode_summary[:3000]}\n</details>")
    lines.append("\n*Information only. Final eligibility is decided by the government department.*")
    return "\n".join(lines)


def run(wt: Path, branch: str, title: str, body: str, decision: str) -> dict[str, Any]:
    if settings.publish_mode == "dry":  # evaluations: commit on the job branch only, never merge
        (wt / ".niyam" / "pr_body.md").write_text(body, encoding="utf-8")
        return {"pr_url": None, "merged": False, "mode": "dry"}
    if settings.publish_mode != "github":
        if decision == "auto_merge":
            root = rulebook.main_path()
            rulebook.git("merge", "-q", "--no-ff", "-m", f"Merge {branch}: {title}", branch, cwd=root)
            return {"pr_url": None, "merged": True, "mode": "local"}
        return {"pr_url": None, "merged": False, "mode": "local"}
    rulebook.git("push", "-q", "-u", "origin", branch, cwd=wt, timeout=300)
    labels = {"auto_merge": "auto-merged", "human_review": "needs-review", "needs_human": "needs-human"}[decision]
    _gh("label", "create", labels, "--force", "--color", {"auto-merged": "2da44e", "needs-review": "d29922", "needs-human": "cf222e"}[labels], cwd=wt)
    proc = _gh("pr", "create", "--repo", settings.rulebook_repo, "--head", branch, "--base", "main",
               "--title", title, "--body", body, "--label", labels, cwd=wt)
    if proc.returncode != 0:
        raise RuntimeError(f"could not open pull request: {proc.stderr.strip()}")
    url = proc.stdout.strip().splitlines()[-1]
    merged = False
    if decision == "auto_merge":
        m = _gh("pr", "merge", url, "--merge", "--delete-branch=false", cwd=wt)
        merged = m.returncode == 0
        if merged:
            rulebook.sync_main()
    return {"pr_url": url, "merged": merged, "mode": "github"}

